def seed_expansion(db):
 owner=db.scalar(select(User).where(User.role=='admin'))
 if not owner:return
 for name,tags in {'Служба 104':['газ','запах газа'],'ЦОДД':['ДТП'],'Мосводоканал':['водопровод'],'МОСГАЗ':['газопровод']}.items():
  if not db.get(ServiceDefinition,name):db.add(ServiceDefinition(name=name,config={'tags':tags,'questions':[],'rules':[]}))
 for index,(service,title,description,street,house,tags) in enumerate(SCENES):
  if not db.get(ServiceDefinition,service):db.add(ServiceDefinition(name=service,config={'tags':tags,'questions':[],'rules':[]}))
  for mode in ('112','dds'):
   marker=f'{"112" if mode=="112" else "ДДС"} · {service}: {title}'
   if db.scalar(select(Ticket.id).where(Ticket.title==marker)):continue
   card={'name':'Иван Сергеевич Соколов','caller_status':'очевидец','country':'Россия','region':'Москва','city':'Москва','street':street,'house':house,'incident_type':title,'victims':'no','description':description,'entrance':'1','floor':'2','phone':'+7 (900) 123-45-67'}
   targets=['Служба 101',service] if 'Задымление' in title else [service]
   details={'children':'Детей рядом со мной нет.','animals':'Животных рядом не вижу.','when':'Заметил примерно две минуты назад.','location':'Я нахожусь на безопасном расстоянии и вижу место происшествия.','access':'Подъезд со стороны улицы свободен.','people_count':'Рядом со мной двое взрослых.','danger':'Близко к опасному участку не подхожу.','fire':'Открытого пламени не вижу.','smoke_source':'Дым идёт из мусоропровода на втором этаже.' if 'Задымление' in title else 'Дыма не вижу.','blocked_people':'Заблокированных людей не вижу.' if 'лифт' not in title.lower() else 'В лифте двое взрослых.'}
   task={'id':f'services020-{index}-{mode}','title':marker,'mode':mode,'intro':description,'category':service,'caller_gender':'male','scenario_details':details,'limit_seconds':600,'own_service':service,'services':targets,'initial_card':card if mode=='dds' else {},'expected_card':card,'type_options':[title],'method_note':'Вымышленный учебный сценарий. Принадлежность объекта и порядок привлечения служб сверяются с регламентом учебного контура.','source':'Каталог тренажёра 0.8.20; учебные обстоятельства и контакты.', 'questions':[], 'criteria':[]}
   if mode=='112':task['criteria']=[{'id':k,'label':label,'kind':'field','field':k,'expected':card[k],'weight':15} for k,label in [('street','Улица'),('house','Дом'),('incident_type','Тип происшествия'),('victims','Пострадавшие')]]+[{'id':f'service{i}','label':'Оповещена '+s,'kind':'service','expected':s,'weight':15} for i,s in enumerate(targets)]
   else:
    task['contacts']=[{'id':'brigade','name':'Руководитель бригады','kind':'brigade','phone':str(1100+index),'response':'Заявку приняли. Выезжаем по указанному адресу.','updates':['Мы прибыли. Обстановка соответствует заявке.','Работы завершены. Опасность устранена.']}]
    task['criteria']=[{'id':'accept','label':'Карточка принята','kind':'status','expected':'Принята','weight':20},{'id':'contact','label':'Сведения переданы бригаде','kind':'contact','expected':'brigade','weight':20},{'id':'done','label':'Работы завершены','kind':'status','expected':'Работы завершены','weight':20},{'id':'comment','label':'Ход работ отражён в комментариях','kind':'manual','expected':'Прибытие бригады, фактические действия и результат работ.','weight':20}]
    task['service_events']=[{'kind':'incoming_call','contact_id':'brigade','trigger_contact':'brigade','who':'Руководитель бригады','after':delay,'text':text} for delay,text in [(20,'Мы прибыли. Обстановка соответствует заявке.'),(50,'Работы завершены. Опасность устранена.')]]
   from .caller import generated_details
   if mode=='112':task['scenario_details']=generated_details(task)
   from .voice import prepare
   data=prepare(TicketData(title=marker,description=description,difficulty_stars=2,tasks=[task]).model_dump(),db,owner.id)
   ticket=Ticket(title=marker,created_by=owner.id);db.add(ticket);db.flush();db.add(TicketVersion(ticket_id=ticket.id,number=1,published=True,data=data))
 existing={q.data.get('seed_key') for q in db.scalars(select(MiniQuestion))}
 items=[{'prompt':p,'answer':a,'kind':'choice','options':opts,'level':1} for p,a,opts in MINIS]
 for word in ['Декабристов','Конёнкова','Мусоропровод','Пострадавшие','Реагирование','Набережная','Ограждение','Электроснабжение','Теплотрасса','Подтопление','Управляющая организация','Подземный переход']:
  items.append({'prompt':'Введите без ошибок: '+word,'answer':word,'kind':'text','options':[],'level':0})
 for index,item in enumerate(items):
  key=f'expansion020-{index}'
  if key not in existing:db.add(MiniQuestion(owner_id=owner.id,data={**item,'seed_key':key}))
 db.commit()
